<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $venue->name }} - Operacao</title><style>:root{--ink:#132238;--muted:#64748b;--page:#f4f7fb;--card:#fff;--green:#10b981;--amber:#f59e0b;--line:#e7edf5}*{box-sizing:border-box}body{margin:0;background:var(--page);color:var(--ink);font:15px/1.45 Inter,system-ui,sans-serif}.shell{max-width:1240px;margin:auto;padding:24px}.hero{background:linear-gradient(115deg,#10243e,#1d4f70);color:#fff;border-radius:24px;padding:28px;display:flex;gap:18px;justify-content:space-between;align-items:flex-end}.eyebrow{margin:0 0 5px;color:#a7e7db;font-weight:700;font-size:12px;letter-spacing:.08em;text-transform:uppercase}.hero h1{margin:0;font-size:clamp(24px,4vw,34px)}.hero p{margin:6px 0 0;color:#d7e4ef}.badge{border:1px solid #ffffff36;background:#ffffff18;padding:8px 12px;border-radius:999px;white-space:nowrap;font-weight:650}.metrics{margin:20px 0;display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.metric,.table-card{background:var(--card);border:1px solid var(--line);border-radius:18px;box-shadow:0 7px 20px #12223d0a}.metric{padding:18px}.metric span{display:block;color:var(--muted);font-size:13px}.metric strong{display:block;margin-top:8px;font-size:25px}.section-title{display:flex;align-items:center;justify-content:space-between;margin:28px 0 12px}.section-title h2{margin:0;font-size:20px}.legend{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:14px}.table-card{padding:18px;position:relative;overflow:hidden}.table-card:before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:var(--green)}.table-card.occupied:before{background:var(--amber)}.table-card-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.table-card h3{margin:0;font-size:18px}.state{font-size:12px;font-weight:700;padding:5px 8px;border-radius:99px;background:#ecfdf5;color:#047857}.occupied .state{background:#fffbeb;color:#b45309}.tab-code{margin:20px 0 0;color:var(--muted);font-size:13px}.empty{padding:40px;text-align:center;border:1px dashed #cbd5e1;border-radius:18px;color:var(--muted);background:#fff}@media(max-width:640px){.shell{padding:14px}.hero{padding:22px;align-items:flex-start;flex-direction:column}.metrics{grid-template-columns:1fr}.grid{grid-template-columns:1fr 1fr}.table-card{padding:14px}}</style></head><body><main class="shell"><header class="hero"><div><p class="eyebrow">Operacao do salao</p><h1>{{ $venue->name }}</h1><p>Acompanhe mesas e comandas sem perder o ritmo do atendimento.</p></div><div class="badge">Atualizacao em tempo real</div></header><section class="metrics" aria-label="Resumo da operacao"><article class="metric"><span>Mesas ocupadas</span><strong>{{ $occupiedTablesCount }}</strong></article><article class="metric"><span>Comandas abertas</span><strong>{{ $openTabsCount }}</strong></article><article class="metric"><span>Vendas de hoje</span><strong>R$ {{ number_format((float) $todaySales, 2, ',', '.') }}</strong></article></section><div class="section-title"><h2>Mapa de mesas</h2><span class="legend">Verde disponivel - amarelo em atendimento</span></div><section class="grid">@forelse($tables as $table)<article class="table-card {{ $table->status }}"><div class="table-card-top"><h3>Mesa {{ $table->code }}</h3><span class="state">{{ $table->status === 'occupied' ? 'Em atendimento' : 'Disponivel' }}</span></div><p class="tab-code">{{ $table->tabs->first()?->code ? 'Comanda '.$table->tabs->first()->code : 'Sem comanda aberta' }}</p></article>@empty<p class="empty">Nenhuma mesa cadastrada ainda.</p>@endforelse</section></main></body></html>
